.mega-grid.cols-3{grid-template-columns:1fr 1fr 1fr}
.mega-grid.cols-4{grid-template-columns:1fr 1fr 1fr 1fr}
.mega-col{padding:0 .8rem;border-right:1px solid var(--border)}
.mega-col:last-child{border-right:none}
.mega-col h4{font-size:.7rem;text-transform:uppercase;letter-spacing:1px;color:var(--primary);font-weight:700;margin:0 0 .6rem 0;padding-bottom:.4rem;border-bottom:2px solid var(--primary-light)}
