    text = p.read_text(encoding="utf-8")
    original = text

    # Only add if functions are referenced but not defined
    if 'window.acceptCookies' in text and 'window.acceptCookies = function' not in text:
        # Add before </body>
        text = text.replace('</body>', CONSENT_SCRIPT + '\n</body>')
        p.write_text(text, encoding="utf-8")
        count += 1

print(f"Articles with consent functions added: {count}")
